func (o *DHCPv6Option) decode(data []byte) error {
	if len(data) < 2 {
		return errors.New("not enough data to decode")
	}
	o.Code = DHCPv6Opt(binary.BigEndian.Uint16(data[0:2]))
	if len(data) < 3 {
		return errors.New("not enough data to decode")
	}
	o.Length = binary.BigEndian.Uint16(data[2:4])
	o.Data = data[4 : 4+o.Length]
	return nil
}
